input.function:
() => {
  const grid = document.querySelector('#plenaria .jet-listing-grid__items') || document.querySelector('#plenaria');
  const items = grid ? Array.from(grid.querySelectorAll('.jet-listing-grid__item')).map(i => i.getAttribute('data-post-id')) : [];
  const titles = grid ? Array.from(grid.querySelectorAll('.elementor-element-4c6562b a')).map(a=>a.textContent.trim()) : [];
  const pag = document.querySelector('.jet-smart-filters-pagination[data-query-id="plenaria"]');
  const current = pag ? pag.querySelector('.jet-filters-pagination__current')?.textContent : null;
  const svgCount = grid ? grid.querySelectorAll('svg').length : 0;
  const imgStyles = grid ? Array.from(grid.querySelectorAll('[style*="background-image"]')).length : 0;
  return {
    domPostIds: items,
    domTitles: titles,
    paginationCurrent: current,
    svgCount,
    bgImageDivs: imgStyles,
    gridHTMLempty: grid ? grid.innerHTML.includes('select listing to show') : 'no-grid'
  };
}

