docker exec -u www-data "$CONTAINER" wp eval '
$queries = \JetEngine\Query_Builder\Manager\Manager::instance()->get_queries();
foreach ($queries as $id => $q) {
  if ($id == 58) {
    echo "ID: $id\n";
    echo "Name: " . $q->get_name() . "\n";
    echo "Type: " . $q->query_type . "\n";
    $args = $q->get_args();
    echo "ARGS:\n"; print_r($args);
  }
}' --path=/var/www/html 2>/dev/null | head -80

