input.function:
() => {
  const items = Array.from(document.querySelectorAll('#plenaria .jet-listing-grid__item'));
  return items.map(item => {
    const postId = item.getAttribute('data-post-id');
    // o container com bg-image é .elementor-element-a9633d8
    const bgEl = item.querySelector('.elementor-element-a9633d8');
    let computedBg = bgEl ? getComputedStyle(bgEl).backgroundImage : 'no-el';
    // checa se o <style> inline do item existe
    const hasStyleTag = !!item.querySelector('style');
    const styleText = item.querySelector('style')?.textContent || '';
    const bgInStyle = styleText.includes('background-image');
    return { postId, computedBg: computedBg.slice(0,90), hasStyleTag, bgInStyle };
  });
}

