() => {
  const pag = document.querySelector('.jet-smart-filters-pagination[data-query-id="plenaria"]');
  if (pag) pag.scrollIntoView({block:'center'});
  const grid = document.querySelector('#plenaria .jet-listing-grid__items');
  const before = grid ? Array.from(grid.querySelectorAll('.jet-listing-grid__item')).map(i=>i.getAttribute('data-post-id')) : [];
  return { paginationFound: !!pag, postIdsBefore: before };
}

() => {
  const grid = document.querySelector('#plenaria .jet-listing-grid__items');
  const after = grid ? Array.from(grid.querySelectorAll('.jet-listing-grid__item')).map(i=>i.getAttribute('data-post-id')) : [];
  const titles = grid ? Array.from(grid.querySelectorAll('.elementor-element-4c6562b a')).map(a=>a.textContent.trim()) : [];
  const pag = document.querySelector('.jet-smart-filters-pagination[data-query-id="plenaria"]');
  const current = pag ? pag.querySelector('.jet-filters-pagination__current,.jet-active')?.textContent : null;
  const bgs = grid ? Array.from(grid.querySelectorAll('.elementor-element-a9633d8')).map(el=>{
    const bg = getComputedStyle(el).backgroundImage;
    return bg && bg !== 'none' ? 'HAS-IMG' : 'NO-IMG';
  }) : [];
  const svgCount = grid ? grid.querySelectorAll('svg').length : 0;
  return { postIdsAfter: after, titles, currentPage: current, bgImageStatus: bgs, svgCount };
}

